      "warningText": {
        "type": "string",
        "description": "赛事临近提醒文本",
        "sampleValue": "注意：赛事临近"
      }
    },
    "modules": {
      "weather": {
        "icon": {
          "type": "string",
          "description": "天气模块文字图标",
          "sampleValue": "☀"
        },
        "summary": {
          "type": "string",
          "description": "天气摘要",
          "sampleValue": "晴22℃"
        }
      },
      "pace": {
        "icon": {
          "type": "string",
          "description": "配速建议模块文字图标",
          "sampleValue": "⚡"
        },
        "summary": {
          "type": "string",
          "description": "配速建议摘要",
          "sampleValue": "6:20配速"
        }
      },
      "gear": {
        "icon": {
          "type": "string",
          "description": "装备清单模块文字图标",
          "sampleValue": "✓"
        },
        "summary": {
          "type": "string",
          "description": "装备清单摘要",
          "sampleValue": "带水鞋"
        }
      }
    }
  },
  "assetCandidates": []
}

